<script setup>
import { computed } from 'vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';

const props = defineProps({
    organization: { type: Object, required: true }, customer: { type: Object, required: true },
    sales: { type: Array, required: true }, openInvoices: { type: Array, required: true },
    generalBalance: { type: String, required: true }, transactions: { type: Array, required: true },
    canManageCustomers: { type: Boolean, required: true }, canManageCustomerAccounts: { type: Boolean, required: true },
    flashMessage: { type: String, default: null }, errorMessage: { type: String, default: null },
});
const editForm = useForm({ code: props.customer.code || '', name: props.customer.name, phone: props.customer.phone || '', email: props.customer.email || '', address: props.customer.address || '', notes: props.customer.notes || '', credit_limit: props.customer.creditLimit || '0.00', is_active: props.customer.isActive });
const accountTransactionLabels = { opening_balance: 'رصيد افتتاحي', sale: 'بيع آجل', payment: 'تحصيل' };
const paymentForm = useForm({ sale_id: props.openInvoices[0]?.id ? String(props.openInvoices[0].id) : '', operation_uuid: uuid(), amount: props.openInvoices[0]?.due || props.generalBalance || '0.00', payment_method: 'cash', reference: '' });
const selectedInvoice = computed(() => props.openInvoices.find((invoice) => String(invoice.id) === String(paymentForm.sale_id)) || null);
function money(value) { return Number(value ?? 0).toLocaleString('ar-EG', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
function uuid() { if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID(); return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => { const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16); }); }
function updateCustomer() { editForm.patch(`/customers/${props.customer.id}`, { preserveScroll: true }); }
function collectPayment() { paymentForm.post(`/customers/${props.customer.id}/payments`, { preserveScroll: true, onSuccess: () => { paymentForm.operation_uuid = uuid(); paymentForm.reference = ''; paymentForm.sale_id = props.openInvoices[0]?.id ? String(props.openInvoices[0].id) : ''; paymentForm.amount = props.openInvoices[0]?.due || props.generalBalance || '0.00'; } }); }
function fillDue() { paymentForm.amount = selectedInvoice.value?.due || props.generalBalance || '0.00'; }
</script>

<template>
    <Head :title="`${customer.name} | حساب العميل | Metrik POS`" />
    <main dir="rtl" class="min-h-screen bg-slate-950 px-4 py-8 text-slate-100 sm:px-6"><section class="mx-auto max-w-7xl space-y-6">
        <header class="flex flex-wrap items-center justify-between gap-4"><div><Link href="/customers" class="text-sm text-emerald-200 hover:underline">← دليل العملاء</Link><p class="mt-4 text-sm font-semibold text-emerald-300">حساب العميل</p><h1 class="mt-1 text-3xl font-black">{{ customer.name }}</h1><p class="mt-2 text-sm text-slate-400">{{ customer.code || 'بدون كود' }} · {{ customer.phone || 'بدون هاتف' }} · {{ organization.name }}</p></div><div class="flex flex-wrap gap-2"><Link :href="`/customers/${customer.id}/statement`" class="rounded-xl border border-white/10 px-4 py-3 font-bold hover:border-emerald-300/60">كشف الحساب الكامل</Link><Link href="/pos" class="rounded-xl bg-emerald-300 px-4 py-3 font-bold text-slate-950">نقطة البيع</Link></div></header>
        <div v-if="flashMessage" class="rounded-xl border border-emerald-300/20 bg-emerald-300/10 px-4 py-3 text-sm text-emerald-200" role="status">{{ flashMessage }}</div><div v-if="errorMessage" class="rounded-xl border border-rose-300/20 bg-rose-300/10 px-4 py-3 text-sm text-rose-200" role="alert">{{ errorMessage }}</div>
        <section class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><article class="rounded-2xl border border-white/10 bg-slate-900 p-5"><p class="text-sm text-slate-400">الرصيد المستحق</p><p class="mt-3 text-2xl font-black" :class="Number(customer.balance) > 0 ? 'text-amber-200' : 'text-emerald-200'">{{ money(customer.balance) }} ج.م</p><p class="mt-2 text-xs text-slate-500">موجب = مبلغ على العميل</p></article><article class="rounded-2xl border border-white/10 bg-slate-900 p-5"><p class="text-sm text-slate-400">الحد الائتماني</p><p class="mt-3 text-2xl font-black">{{ money(customer.creditLimit) }} ج.م</p><p class="mt-2 text-xs text-slate-500">البيع الآجل يتطلب حدًا أكبر من صفر ومساحة متاحة.</p></article><article class="rounded-2xl border border-white/10 bg-slate-900 p-5"><p class="text-sm text-slate-400">فواتير آجل مفتوحة</p><p class="mt-3 text-2xl font-black">{{ openInvoices.length }}</p><p class="mt-2 text-xs text-slate-500">{{ money(openInvoices.reduce((sum, invoice) => sum + Number(invoice.due), 0)) }} ج.م متبقية على الفواتير</p></article><article class="rounded-2xl border border-white/10 bg-slate-900 p-5"><p class="text-sm text-slate-400">الرصيد العام</p><p class="mt-3 text-2xl font-black">{{ money(generalBalance) }} ج.م</p><p class="mt-2 text-xs text-slate-500">مثل الرصيد الافتتاحي غير المرتبط بفاتورة.</p></article></section>

        <section v-if="canManageCustomers" class="rounded-2xl border border-white/10 bg-slate-900 p-5 sm:p-6"><h2 class="text-xl font-bold">بيانات العميل والحد الائتماني</h2><form class="mt-4 grid gap-4 md:grid-cols-2 xl:grid-cols-3" @submit.prevent="updateCustomer">
            <label class="text-sm"><span class="mb-2 block">الاسم *</span><input v-model="editForm.name" required maxlength="180" class="w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3" /><span v-if="editForm.errors.name" class="text-rose-300">{{ editForm.errors.name }}</span></label>
            <label class="text-sm"><span class="mb-2 block">الكود</span><input v-model="editForm.code" maxlength="40" class="w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3" /><span v-if="editForm.errors.code" class="text-rose-300">{{ editForm.errors.code }}</span></label>
            <label class="text-sm"><span class="mb-2 block">الهاتف</span><input v-model="editForm.phone" maxlength="40" class="w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3" /><span v-if="editForm.errors.phone" class="text-rose-300">{{ editForm.errors.phone }}</span></label>
            <label class="text-sm"><span class="mb-2 block">البريد الإلكتروني</span><input v-model="editForm.email" type="email" maxlength="180" class="w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3" /><span v-if="editForm.errors.email" class="text-rose-300">{{ editForm.errors.email }}</span></label>
            <label class="text-sm"><span class="mb-2 block">الحد الائتماني (ج.م)</span><input v-model="editForm.credit_limit" type="number" min="0" step="0.01" required class="w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3" /><span v-if="editForm.errors.credit_limit" class="text-rose-300">{{ editForm.errors.credit_limit }}</span></label>
            <label class="flex items-center gap-3 rounded-xl border border-white/10 px-4 py-3 text-sm"><input v-model="editForm.is_active" type="checkbox" class="size-4 accent-emerald-300" />حساب العميل نشط ويمكن اختياره في البيع</label>
            <label class="text-sm md:col-span-2 xl:col-span-3"><span class="mb-2 block">العنوان</span><input v-model="editForm.address" maxlength="500" class="w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3" /></label>
            <label class="text-sm md:col-span-2 xl:col-span-3"><span class="mb-2 block">ملاحظات</span><textarea v-model="editForm.notes" rows="2" maxlength="3000" class="w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3"></textarea></label>
            <div class="flex justify-end xl:col-span-3"><button :disabled="editForm.processing" class="rounded-xl bg-emerald-300 px-5 py-3 font-bold text-slate-950 disabled:opacity-50">{{ editForm.processing ? 'جارٍ الحفظ...' : 'حفظ التعديلات' }}</button></div>
        </form></section>

        <section v-if="canManageCustomerAccounts" class="rounded-2xl border border-emerald-300/20 bg-slate-900 p-5 sm:p-6"><h2 class="text-xl font-bold">تحصيل من حساب العميل</h2><p class="mt-1 text-sm text-slate-400">اختر فاتورة آجل لتقليل متبقيها، أو اختر الرصيد العام لتحصيل الرصيد الافتتاحي غير المرتبط بفواتير آجل.</p><form class="mt-5 grid gap-4 md:grid-cols-2 xl:grid-cols-4" @submit.prevent="collectPayment">
            <label class="text-sm xl:col-span-2"><span class="mb-2 block">الفاتورة / الرصيد العام</span><select v-model="paymentForm.sale_id" @change="fillDue" class="w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3"><option value="" :disabled="Number(generalBalance) <= 0">الرصيد العام — {{ money(generalBalance) }} ج.م</option><option v-for="invoice in openInvoices" :key="invoice.id" :value="String(invoice.id)">{{ invoice.invoiceNumber }} — المتبقي {{ money(invoice.due) }} ج.م</option></select><span v-if="paymentForm.errors.sale_id" class="mt-1 block text-rose-300">{{ paymentForm.errors.sale_id }}</span></label>
            <label class="text-sm"><span class="mb-2 block">المبلغ (ج.م)</span><input v-model="paymentForm.amount" type="number" min="0.01" step="0.01" required class="w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3" /><span v-if="paymentForm.errors.amount" class="mt-1 block text-rose-300">{{ paymentForm.errors.amount }}</span></label>
            <label class="text-sm"><span class="mb-2 block">طريقة التحصيل</span><select v-model="paymentForm.payment_method" class="w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3"><option value="cash">نقدي (يتطلب وردية مفتوحة)</option><option value="card">بطاقة</option><option value="mobile_wallet">محفظة إلكترونية</option><option value="other">أخرى</option></select><span v-if="paymentForm.errors.payment_method" class="mt-1 block text-rose-300">{{ paymentForm.errors.payment_method }}</span></label>
            <label class="text-sm md:col-span-2"><span class="mb-2 block">مرجع الدفع الخارجي (اختياري)</span><input v-model="paymentForm.reference" maxlength="120" class="w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3" /><span v-if="paymentForm.errors.reference" class="mt-1 block text-rose-300">{{ paymentForm.errors.reference }}</span></label>
            <div class="flex items-end justify-end xl:col-span-2"><button :disabled="paymentForm.processing || Number(paymentForm.amount) <= 0" class="rounded-xl bg-emerald-300 px-6 py-3 font-black text-slate-950 disabled:opacity-50">{{ paymentForm.processing ? 'جارٍ التسجيل...' : 'تسجيل التحصيل' }}</button></div>
        </form><p v-if="paymentForm.errors.operation_uuid" class="mt-3 text-sm text-rose-300">{{ paymentForm.errors.operation_uuid }}</p></section>

        <section class="rounded-2xl border border-white/10 bg-slate-900 p-5 sm:p-6"><div class="flex items-center justify-between gap-3"><h2 class="text-xl font-bold">سجل الفواتير</h2><span class="text-xs text-slate-500">آخر {{ sales.length }} فاتورة</span></div><div v-if="!sales.length" class="mt-4 rounded-xl border border-dashed border-white/10 p-6 text-center text-slate-400">لا توجد فواتير مرتبطة بهذا العميل.</div><div v-else class="mt-4 overflow-x-auto"><table class="w-full min-w-[700px] text-right text-sm"><thead class="text-slate-400"><tr><th class="px-3 py-3">الفاتورة</th><th class="px-3 py-3">الفرع</th><th class="px-3 py-3">الإجمالي</th><th class="px-3 py-3">المحصّل</th><th class="px-3 py-3">المتبقي</th><th class="px-3 py-3">التاريخ</th><th class="px-3 py-3"></th></tr></thead><tbody><tr v-for="sale in sales" :key="sale.id" class="border-t border-white/5"><td class="px-3 py-3 font-semibold">{{ sale.invoiceNumber }}</td><td class="px-3 py-3">{{ sale.branchName || '—' }}</td><td class="px-3 py-3">{{ money(sale.total) }}</td><td class="px-3 py-3">{{ money(sale.paid) }}</td><td class="px-3 py-3" :class="Number(sale.due) > 0 ? 'text-amber-200' : 'text-emerald-200'">{{ money(sale.due) }}</td><td class="px-3 py-3 text-slate-400">{{ sale.soldAt }}</td><td class="px-3 py-3"><Link :href="`/sales/${sale.id}`" class="text-emerald-200 hover:underline">فتح</Link></td></tr></tbody></table></div></section>

        <section class="rounded-2xl border border-white/10 bg-slate-900 p-5 sm:p-6"><h2 class="text-xl font-bold">كشف الحساب</h2><div v-if="!transactions.length" class="mt-4 text-sm text-slate-400">لا توجد حركات حساب مسجلة بعد.</div><div v-else class="mt-4 overflow-x-auto"><table class="w-full min-w-[820px] text-right text-sm"><thead class="text-slate-400"><tr><th class="px-3 py-3">التاريخ</th><th class="px-3 py-3">الحركة</th><th class="px-3 py-3">الوصف</th><th class="px-3 py-3">مدين</th><th class="px-3 py-3">دائن</th><th class="px-3 py-3">الرصيد بعد الحركة</th><th class="px-3 py-3">المستخدم</th></tr></thead><tbody><tr v-for="entry in transactions" :key="entry.id" class="border-t border-white/5"><td class="px-3 py-3 text-slate-400">{{ entry.createdAt }}</td><td class="px-3 py-3">{{ accountTransactionLabels[entry.type] || entry.type }}</td><td class="px-3 py-3">{{ entry.description || entry.reference || entry.saleNumber || '—' }}</td><td class="px-3 py-3">{{ money(entry.debit) }}</td><td class="px-3 py-3">{{ money(entry.credit) }}</td><td class="px-3 py-3 font-bold">{{ money(entry.balanceAfter) }}</td><td class="px-3 py-3">{{ entry.createdBy || '—' }}</td></tr></tbody></table></div></section>
    </section></main>
</template>
